function relayComponent(start){if(!relayBoard[start]||!game?.satelliteBoard)return[];const rows=game.satelliteBoard.rows,cols=game.satelliteBoard.cols,id=relayBoard[start].id,seen=new Set(),stack=[start];while(stack.length){const i=stack.pop();if(seen.has(i)||relayBoard[i]?.id!==id)continue;seen.add(i);const r=Math.floor(i/cols),c=i%cols;for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){if(!dr&&!dc)continue;const rr=r+dr,cc=c+dc;if(rr>=0&&rr<rows&&cc>=0&&cc<cols){const n=rr*cols+cc;if(!seen.has(n)&&relayBoard[n]?.id===id)stack.push(n)}}}return[...seen]}
