   const rs=currentRuns();if(!rs.length)break;
   combo++;currentCombo=combo;bestCombo=Math.max(bestCombo,combo);showComboBurst(combo,opts.specialCombo?'SPECIAL RUSH':'RUSH');if(game.satelliteBoard&&combo>=Number(config.multiBoard?.cascadeChargeThreshold||2))addRelayCharge(1);renderHud();await delay(animMs('cascadeGapMs'));
