function spreadOne(type){const sources=[...blockersMap.entries()].filter(([,b])=>b?.type===type);if(!sources.length)return null;const cap=Math.max(1,Number(config.blockers?.maximumCells)||18);if(blockersMap.size>=cap)return null;const candidates=[];for(const [i] of sources)for(const n of Board.orthogonalNeighbors?.(Number(i),game.board.rows,game.board.cols)||[])if(!inactive(n)&&!blockersMap.has(n)&&board[n])candidates.push(n);const unique=[...new Set(candidates)];unique.sort((a,b)=>{const ao=objectives.get(norm(board[a]?.id)),bo=objectives.get(norm(board[b]?.id));return (ao?.outstanding>0?1:0)-(bo?.outstanding>0?1:0)});for(let tries=0;tries<Math.min(10,unique.length);tries++){const span=Math.max(1,Math.ceil(unique.length*.72)),pick=unique[Math.floor(rng()*span)];blockersMap.set(pick,{type,layer:type==='mud'?2:1});if(isPlayableNow()){if(type==='vine')FX?.vineCreep?.([pick]);else FX?.hazard?.([pick],type);return pick}blockersMap.delete(pick);unique.splice(unique.indexOf(pick),1)}return null}
function relocateBees(){const bees=[...blockersMap.entries()].filter(([,b])=>b?.type==='bee');if(!bees.length)return[];const moved=[];for(const [from,bl] of bees.slice(0,Math.max(1,Number(config.hazards?.bee?.maximumMovesPerCycle)||2))){const ns=(Board.orthogonalNeighbors?.(Number(from),game.board.rows,game.board.cols)||[]).filter(n=>!inactive(n)&&board[n]&&!blockersMap.has(n));if(!ns.length)continue;ns.sort((a,b)=>{const score=n=>(Board.orthogonalNeighbors?.(n,game.board.rows,game.board.cols)||[]).some(x=>['flower','honey'].includes(blocker(x)?.type))?0:1;return score(a)-score(b)});const to=ns[Math.floor(rng()*Math.max(1,Math.ceil(ns.length*.55)))];blockersMap.delete(Number(from));blockersMap.set(to,{type:'bee',layer:Math.max(1,Number(bl.layer)||1)});if(isPlayableNow())moved.push(to);else{blockersMap.delete(to);blockersMap.set(Number(from),bl)}}if(moved.length){play('bee',.12);FX?.hazard?.(moved,'bee')}return moved}
function sinkQuicksand(){const cells=[...blockersMap.entries()].filter(([,b])=>b?.type==='quicksand').map(([i])=>Number(i)).filter(i=>board[i]);if(!cells.length)return[];cells.sort((a,b)=>{const ao=objectives.get(norm(board[a]?.id)),bo=objectives.get(norm(board[b]?.id));return (ao?.outstanding>0?1:0)-(bo?.outstanding>0?1:0)});const max=Math.max(1,Number(config.hazards?.quicksand?.maximumSinksPerCycle)||1),out=[];for(const i of cells.slice(0,max)){const filler=(game.activeIngredientPool||[]).filter(id=>!(objectives.get(norm(id))?.outstanding>0));const id=filler.length?filler[Math.floor(rng()*filler.length)]:weightedPick();board[i]=piece(id);out.push(i)}if(out.length){play('quicksand',.16);FX?.hazard?.(out,'quicksand')}return out}

