function consumeTurn(){turnsUsed++;if(game.limitType==='moves')game.movesRemaining=Math.max(0,game.movesRemaining-1);if(game.soloOrDuo==='duo'){game.activePlayer=Rand.nextDuoPlayer(game.activePlayer,config);game.nextDuoPlayer=Rand.nextDuoPlayer(game.activePlayer,config)}}
