window.addEventListener('feed-him-meow:booster-request',e=>{if(!document.getElementById('page4')?.classList.contains('is-active'))return;const accepted=acceptOnyx(e.detail?.id,false);if(accepted)e.detail.accepted=accepted});
window.addEventListener('feed-him-meow:booster-cancel-request',()=>{armed=null;imperialFirst=null;window.FeedHimMeowRun?.clearOnyxBooster?.();applyHighlights();renderBoosters()});
$('#gardenReplay')?.addEventListener('click',()=>setup());$('#gardenContinue')?.addEventListener('click',()=>{resetResult();window.feedHimMeowActivatePage?.('page1')});$('#gardenBack')?.addEventListener('click',()=>window.feedHimMeowActivatePage?.('page1'));$('#gardenRescue')?.addEventListener('click',useRetrySafety);
window.addEventListener('feed-him-meow:page-changed',e=>{if(e.detail?.page==='page4'){fitGardenCanvas();setup()}else{resolutionSerial++;resolving=false;pointerTracing=false;swipeStart=null;stopMusic();clearInterval(idleTimer);idleTimer=null;clearCellMarks()}});window.addEventListener('resize',fitGardenCanvas);if(typeof ResizeObserver!=='undefined'){new ResizeObserver(()=>fitGardenCanvas()).observe(document.getElementById('page4'))}window.addEventListener('feed-him-meow:audio-settings',()=>{if(document.getElementById('page4')?.classList.contains('is-active'))startMusic();else stopMusic()});

